package com.medtrack.transfer.entity; import com.medtrack.shared.exception.ConflictException; import java.util.*; public final class TransferStateMachine {private static final Map<TransferStatus,Set<TransferStatus>> ALLOWED=Map.ofEntries(Map.entry(TransferStatus.DRAFT,Set.of(TransferStatus.REQUESTED,TransferStatus.CANCELLED)),Map.entry(TransferStatus.REQUESTED,Set.of(TransferStatus.APPROVED,TransferStatus.REJECTED,TransferStatus.CANCELLED)),Map.entry(TransferStatus.APPROVED,Set.of(TransferStatus.ALLOCATED,TransferStatus.CANCELLED)),Map.entry(TransferStatus.ALLOCATED,Set.of(TransferStatus.PICKED,TransferStatus.CANCELLED)),Map.entry(TransferStatus.PICKED,Set.of(TransferStatus.PACKED,TransferStatus.CANCELLED)),Map.entry(TransferStatus.PACKED,Set.of(TransferStatus.DISPATCHED,TransferStatus.CANCELLED)),Map.entry(TransferStatus.DISPATCHED,Set.of(TransferStatus.RECEIVED)),Map.entry(TransferStatus.RECEIVED,Set.of(TransferStatus.COMPLETED,TransferStatus.DISCREPANCY_FLAGGED)),Map.entry(TransferStatus.DISCREPANCY_FLAGGED,Set.of()));private TransferStateMachine(){}public static void assertAllowed(TransferStatus from,TransferStatus to){if(!ALLOWED.getOrDefault(from,Set.of()).contains(to))throw new ConflictException("INVALID_TRANSFER_TRANSITION","Cannot transition transfer from "+from+" to "+to);}}
